import{C as r,u as m,j as s,S as i}from"./index-D5mbYTOj.js";import{L as h}from"./react-vendor-AIXwcq2c.js";const{fromYear:o,toYear:c}=r,l=r.interviews.toLocaleString("ru-RU"),x=[{q:"Что такое Altovisas?",a:`Altovisas помогает бесплатно подготовиться к собеседованию на студенческую визу США (F-1). Вы рассказываете о себе, отвечаете на вопросы, а сервис показывает, где консульский офицер, скорее всего, засомневается в кейсе, похожем на ваш. В основе лежат ${l} отзывов, которые сами заявители написали о своих собеседованиях с ${o} по ${c} год.`},{q:"Как это работает?",a:"Вы коротко рассказываете о себе: университет, программа, кто платит за учёбу, консульство. Затем своими словами отвечаете на три вопроса собеседования. Мы сравниваем ваши ответы с отзывами из базы и показываем, к чему офицер, скорее всего, будет придираться, и какие цифры за этим стоят. Это занимает 3 минуты, нужен бесплатный аккаунт."},{q:"Это бесплатно?",a:"Да, проверка профиля бесплатная. Нужен бесплатный аккаунт: он хранит ваши раунды и прогресс. Банковская карта не нужна. Статистика на сайте открыта для всех, даже без аккаунта."},{q:"Откуда берутся данные о собеседованиях?",a:`База состоит из ${l} отзывов о собеседованиях на визу F-1 с ${o} по ${c} год. Их написали сами заявители и выложили в открытом доступе. Мы убрали повторы и разобрали каждый отзыв по вопросам. Каждый месяц добавляется примерно 200 новых.`},{q:"Может ли Altovisas предсказать, дадут ли мне визу?",a:"Нет, и ни один сервис этого не может. Отзывы пишут не все, а только те, кто сам решил поделиться, поэтому доля одобрений в базе описывает именно этих людей, а не реальную картину в консульстве. Закономерности в данных показывают, что явления встречаются вместе, но не что одно вызывает другое. Ничто на сайте не предсказывает исход вашего собеседования: решение о визе принимает только консульский офицер."},{q:"О чём спрашивают на собеседовании на F-1?",a:"Чаще всего в базе встречаются вопросы о том, как оплачивается учёба и кто спонсор, кем работает спонсор и сколько он зарабатывает, в какие ещё университеты вы подавали, что вы закончили раньше и с какими оценками, почему выбрали именно этот университет и эту программу, а также что планируете делать после учёбы. Набор вопросов заметно отличается от консульства к консульству."},{q:"Сколько длится собеседование?",a:"В большинстве отзывов у окошка задают четыре-пять вопросов за две-три минуты. Времени так мало, что важнее всего первый ответ на каждую тему, а не длинные объяснения."},{q:"Какие документы брать с собой?",a:"Список определяет консульство, а не мы, и он меняется. Проверьте инструкции вашего консульства на travel.state.gov и уточните у сотрудника университета, который отвечает за иностранных студентов (DSO). Чаще всего заявители берут форму I-20, подтверждение DS-160, квитанцию об оплате сбора SEVIS, паспорт, письмо о зачислении и финансовые документы."},{q:"Нужно ли заучивать ответы, которые предлагает Altovisas?",a:"Нет. Наши подсказки касаются структуры ответа: с чего начать, что убрать, сколько подробностей добавить. Факты в ответе должны быть вашими и правдивыми. Если сообщить консульскому офицеру ложные существенные сведения, последствия могут остаться на всю жизнь."},{q:"Это юридическая или иммиграционная консультация?",a:"Нет. Altovisas только тренажёр, а не юридическая фирма. Он не связан ни с Госдепартаментом США, ни с каким-либо посольством, консульством или другим государственным органом. За советом по вашему делу обращайтесь к лицензированному иммиграционному адвокату."},{q:"Мои данные в безопасности?",a:"Ваш профиль и ответы видны только вам в вашем аккаунте. Мы никому их не показываем, не продаём и не публикуем. Вы можете в любой момент попросить удалить всё, написав нам. В Политике конфиденциальности подробно описано, что мы собираем, кто это обрабатывает и как долго хранится."},{q:"Можно ли тренироваться несколько раз?",a:"Да. Проверку профиля можно пройти на разных наборах ответов, а после короткого опроса вы получите дополнительные раунды."}],j={ru:{title:"Вопросы о собеседовании на визу F-1",lede:"О чём спрашивают офицеры, как собраны данные Altovisas и что они могут и не могут сказать.",moreTitle:"Остался вопрос?",more:(e,t)=>s.jsxs(s.Fragment,{children:["Напишите на ",e," или прочитайте, ",t("как работает Altovisas"),"."]})}};function p(){const e=m(j),t=s.jsx("a",{href:`mailto:${i.contact}`,children:i.contact}),n=a=>s.jsx(h,{to:"/about",children:a});return s.jsx("div",{className:"tf",children:s.jsxs("article",{className:"page-w doc",children:[s.jsx("h1",{children:e.title}),s.jsx("p",{className:"lede",children:e.lede}),s.jsx("div",{className:"doc-qa",children:x.map(({q:a,a:d})=>s.jsxs("section",{children:[s.jsx("h2",{children:a}),s.jsx("p",{children:d})]},a))}),s.jsxs("section",{className:"doc-end",children:[s.jsx("h2",{children:e.moreTitle}),s.jsx("p",{children:e.more(t,n)})]})]})})}export{p as default};
